            yesterday_bids.append(float(prev['bid']))

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_bid * 1.1, 90.0))
    elif my_status['hp'] > 8:
        bid = min(my_status['budget'], max(avg_bid * 0.5, 20.0))
